let lastDeleted=null;
function renderMiiverse(){if(!state)return;const index=PlazaCatalog.catalog(allNotes(),state.homeCatalog||state.apps,snapshot?.account?.id||state.accountID);if(!index.sections.some(s=>s.id===miiverseSection))miiverseSection='all';$('#communities').replaceChildren(...index.sections.map(section=>{const b=button(section.label+' · '+section.count,()=>{miiverseSection=section.id;focusedNote=null;currentNoteFilter=null;renderMiiverse();});if(section.app){const art=element('span',undefined,'community-icon');if(section.app.icon){const image=element('img');image.src=section.app.icon;image.alt='';art.append(image);}else{art.textContent=section.label.slice(0,1);fillAppIcon(section.app,art);}b.prepend(art);}b.classList.toggle('selected',section.id===miiverseSection);return b;}));renderNotes(currentNoteFilter,PlazaCatalog.filtered(index,miiverseSection,$('#miiverse-search').value,$('#miiverse-sort').value),'#miiverse-notes');}
const categories=[['sound','Music & Sound','♫','#ec8420'],['apps','Home Screen','▦','#2fa1d4'],['display','Screen & Startup','▣','#3b9e9f'],['motion','Miis & Motion','♟','#6fa835'],['friends','Discord & Friends','♟♟','#eb8c38'],['appearance','Mii Appearance','◉','#c76e91'],['data','Data Management','▤','#578dc2'],['updates','System Update','↓','#d49830'],['system','System & Recovery','⚒','#82929b']];
function selectSettings(id){settingsCategory=id;$('#settings-heading').textContent=categories.find(c=>c[0]===id)?.[1]||'System Settings';$('#settings-tiles').hidden=!!id;$('#settings-categories').hidden=!id;for(const field of $('#settings').querySelectorAll('fieldset')){const label=field.querySelector('legend')?.textContent;field.hidden=!id||categories.find(c=>c[0]===id)?.[1]!==label;}for(const tile of $('#settings-strip').children)tile.classList.toggle('selected',tile.dataset.category===id);}
for(const[id,label,icon,color]of categories){const tile=button('',()=>selectSettings(id));tile.setAttribute('aria-label',label+' settings');const art=element('span',icon);art.style.color=color;tile.append(art,element('strong',label));$('#settings-tiles').append(tile);const shortcut=button(icon,()=>selectSettings(id));shortcut.title=label;shortcut.setAttribute('aria-label',label+' settings shortcut');shortcut.dataset.category=id;$('#settings-strip').append(shortcut);}
$('#settings-categories').onclick=()=>selectSettings(null);
$('#miiverse-search').oninput=()=>{focusedNote=null;currentNoteFilter=null;renderMiiverse();};$('#miiverse-sort').onchange=renderMiiverse;$('#miiverse-write').onclick=()=>{const index=PlazaCatalog.catalog(allNotes(),state.homeCatalog||state.apps,snapshot?.account?.id||state.accountID),app=index.sections.find(s=>s.id===miiverseSection)?.app;openComposer(undefined,app?{label:app.label,bundleID:app.bundleID,steamAppID:app.steamAppID||null}:null);};$('#miiverse-volume').oninput=()=>run(async()=>apply(await call('settings',{miiverseMusicVolume:Number($('#miiverse-volume').value)})));
function updateComposerIdentity(){$('#composer-author-label').hidden=$('#visibility').value!=='private';$('#composer-identity').textContent=$('#visibility').value==='public'?'Posting as '+(snapshot?.account?.displayName||'your linked Discord account')+' with your primary Mii.':'Private · Only on this computer, with your selected local Mii.';}
$('#visibility').onchange=updateComposerIdentity;
const undoDelete=button('Undo Delete',async()=>{if(!lastDeleted)return;const note={...lastDeleted,id:lastDeleted.sourceID||lastDeleted.id};lastDeleted=null;apply(await call('note',{note,visibility:note.private?'private':'public',preserveDraft:true}));undoDelete.hidden=true;});undoDelete.id='undo-note-delete';undoDelete.hidden=true;$('#miiverse .section-heading').append(undoDelete);
$('#ui-sound-volume').oninput=()=>run(async()=>apply(await call('settings',{uiSoundVolume:Number($('#ui-sound-volume').value)})));$('#test-click').onclick=()=>PlazaUISounds.play('uiClick',true);$('#test-back').onclick=()=>PlazaUISounds.play('uiBack',true);
$('#import-pack').onclick=()=>run(async()=>{const pack=await call('preparePack');if(!pack)return;const box=element('div');box.className='pack-validation';document.body.append(box);let surface;try{$('#resource-status').textContent='Validating faces, bodies and recordings…';surface=new plazaScene.Surface(box,'portrait',pack.resources);await surface.ready;const payload=await call('engine',{command:'renderAvatar',args:{avatar:state.document.avatar}});await surface.call('portrait',[payload,0,1,false,128,192]);for(const track of pack.music)await validateAudio(track.url);const result=await call('commitPack',pack.token);await plazaScene.reload();sceneSignature='';apply(await call('state'));$('#resource-status').textContent='Installed '+result.animationCount+' animations and '+result.musicCount+' soundtracks. Previous resources and music selections were backed up.';}finally{surface?.dispose();box.remove();await call('discardPack',pack.token);}});
async function validateAudio(url){const audio=new Audio();audio.preload='auto';try{await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Recording validation timed out.')),15000);audio.onloadedmetadata=()=>{clearTimeout(timeout);Number.isFinite(audio.duration)&&audio.duration>0?resolve():reject(Error('Unplayable recording.'));};audio.onerror=()=>{clearTimeout(timeout);reject(Error('The pack contains an unplayable recording.'));};audio.src=url;audio.load();});}finally{audio.removeAttribute('src');audio.load();}}
$('#export-diagnostics').onclick=()=>$('#diagnostics-dialog').showModal();$('#cancel-diagnostics').onclick=()=>$('#diagnostics-dialog').close();$('#save-diagnostics').onclick=()=>run(async()=>{const result=await call('exportDiagnostics',$('#tester-notes').value);if(result.exported){$('#diagnostics-dialog').close();status('Diagnostics exported. Review the ZIP before sharing it.');}});$('#email-diagnostics').onclick=()=>run(()=>call('emailDiagnostics'));

$('#check-updates').onclick=()=>run(async()=>apply(await call('updateCheck')));$('#download-update').onclick=()=>run(async()=>apply(await call('updateDownload')));$('#install-update').onclick=()=>run(()=>call('updateInstall'));for(const[id,key]of [['automatic-update-checks','automaticUpdateChecks'],['automatic-update-downloads','automaticUpdateDownloads']])$('#'+id).onchange=()=>run(async()=>apply(await call('updatePreferences',{[key]:$('#'+id).checked})));
